-- Extend the authoritative ledger; never copy a transaction into a second ledger.
CREATE TABLE org_units(id INTEGER PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('department','cost_centre','category')),code TEXT NOT NULL,name TEXT NOT NULL,actor_id INTEGER REFERENCES users(id),UNIQUE(kind,code));
INSERT INTO org_units(kind,code,name) VALUES('category','RENT','Office rent'),('category','UTILITIES','Utilities'),('category','COMMS','Communications'),('category','ADMIN','Administration'),('category','PROFESSIONAL','Professional fees'),('category','PURCHASES','General purchases'),('category','OTHER','Other operating expenses');
CREATE TABLE org_funds(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,restricted INTEGER NOT NULL CHECK(restricted IN(0,1)),categories TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,treatment TEXT NOT NULL CHECK(treatment IN('income','deferred','refundable')),recognize_receivable INTEGER NOT NULL CHECK(recognize_receivable IN(0,1)),allow_transfers INTEGER NOT NULL CHECK(allow_transfers IN(0,1)),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_fund_approvals(fund_id INTEGER PRIMARY KEY REFERENCES org_funds(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE journal_lines_new(id INTEGER PRIMARY KEY,journal_id INTEGER NOT NULL REFERENCES journals(id),account_id INTEGER NOT NULL REFERENCES accounts(id),project_id INTEGER REFERENCES projects(id),source_id INTEGER REFERENCES funding_sources(id),amount INTEGER NOT NULL CHECK(amount<>0 AND abs(amount)<=1000000000000),org_fund_id INTEGER REFERENCES org_funds(id),department_id INTEGER REFERENCES org_units(id),cost_centre_id INTEGER REFERENCES org_units(id),CHECK((project_id IS NOT NULL AND source_id IS NOT NULL AND org_fund_id IS NULL) OR (project_id IS NULL AND source_id IS NULL AND org_fund_id IS NOT NULL)));
INSERT INTO journal_lines_new(id,journal_id,account_id,project_id,source_id,amount) SELECT id,journal_id,account_id,project_id,source_id,amount FROM journal_lines;
DROP TABLE journal_lines;
ALTER TABLE journal_lines_new RENAME TO journal_lines;
CREATE INDEX journal_dimensions ON journal_lines(project_id,source_id,account_id);
CREATE INDEX idx_journal_lines_project ON journal_lines(project_id,journal_id);
CREATE INDEX org_journal_dimensions ON journal_lines(org_fund_id,department_id,cost_centre_id,journal_id);
CREATE TRIGGER lines_no_update BEFORE UPDATE ON journal_lines WHEN (SELECT state FROM journals WHERE id=OLD.journal_id)='posted' BEGIN SELECT RAISE(ABORT,'Posted journal lines are immutable'); END;
CREATE TRIGGER lines_no_delete BEFORE DELETE ON journal_lines WHEN (SELECT state FROM journals WHERE id=OLD.journal_id)='posted' BEGIN SELECT RAISE(ABORT,'Posted journal lines are immutable'); END;
CREATE TRIGGER lines_no_insert BEFORE INSERT ON journal_lines WHEN (SELECT state FROM journals WHERE id=NEW.journal_id)='posted' BEGIN SELECT RAISE(ABORT,'Posted journal lines are immutable'); END;
INSERT INTO accounts(code,name,type) VALUES('1350','Organization receivables','asset');
INSERT INTO acc_account_profiles(account_id,effective_date,name,reporting_type,reporting_group,control_role,active,cash_flow,reason) SELECT id,'0001-01-01',name,'asset','Receivables','org_receivable',1,'operating','Organization receivable control' FROM accounts WHERE code='1350';
INSERT INTO acc_mappings(role,account_id,effective_date,reason) SELECT 'org_receivable',id,'0001-01-01','Organization receivable control' FROM accounts WHERE code='1350';
CREATE TABLE org_documents(document_id INTEGER PRIMARY KEY REFERENCES acc_documents(id),kind TEXT NOT NULL,spec TEXT NOT NULL);
CREATE TABLE org_promise_posts(document_id INTEGER PRIMARY KEY REFERENCES acc_documents(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_budget_versions(id INTEGER PRIMARY KEY,code TEXT NOT NULL,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('independent','parent')),department_id INTEGER REFERENCES org_units(id),cost_centre_id INTEGER REFERENCES org_units(id),project_ids TEXT NOT NULL,lines TEXT NOT NULL,previous_id INTEGER REFERENCES org_budget_versions(id),reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL);
CREATE TABLE org_budget_approvals(budget_id INTEGER PRIMARY KEY REFERENCES org_budget_versions(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_reservations(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES acc_documents(id),budget_code TEXT NOT NULL,category TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount<>0),date TEXT NOT NULL,journal_id INTEGER REFERENCES journals(id));
CREATE TABLE org_costs(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES acc_documents(id),journal_id INTEGER NOT NULL REFERENCES journals(id),budget_code TEXT,category TEXT NOT NULL,org_fund_id INTEGER REFERENCES org_funds(id),department_id INTEGER REFERENCES org_units(id),cost_centre_id INTEGER REFERENCES org_units(id),project_id INTEGER REFERENCES projects(id),request_line_id INTEGER REFERENCES request_lines(id),amount INTEGER NOT NULL CHECK(amount<>0),origin_id INTEGER REFERENCES org_costs(id));
CREATE TABLE org_allocations(document_id INTEGER PRIMARY KEY REFERENCES acc_documents(id),origin_id INTEGER NOT NULL REFERENCES org_costs(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE org_items(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL UNIQUE REFERENCES acc_documents(id),kind TEXT NOT NULL CHECK(kind IN('bill','reimbursement','receivable','advance')),party TEXT NOT NULL,external_reference TEXT NOT NULL,date TEXT NOT NULL,due_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),UNIQUE(kind,party,external_reference));
CREATE TABLE org_item_movements(id INTEGER PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES org_items(id),document_id INTEGER NOT NULL UNIQUE REFERENCES acc_documents(id),journal_id INTEGER NOT NULL REFERENCES journals(id),amount INTEGER NOT NULL CHECK(amount>0),kind TEXT NOT NULL);
CREATE TABLE org_schedules(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,template TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_schedule_drafts(schedule_id INTEGER NOT NULL REFERENCES org_schedules(id),occurrence TEXT NOT NULL,document_id INTEGER NOT NULL UNIQUE REFERENCES acc_documents(id),PRIMARY KEY(schedule_id,occurrence));
CREATE TABLE org_asset_register(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL UNIQUE REFERENCES acc_documents(id),cost_id INTEGER NOT NULL UNIQUE REFERENCES org_costs(id),code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,cost INTEGER NOT NULL,residual INTEGER NOT NULL,life_months INTEGER NOT NULL,in_service_date TEXT NOT NULL,custodian TEXT NOT NULL,location TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_asset_approvals(asset_id INTEGER PRIMARY KEY REFERENCES org_asset_register(id),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_asset_cancellations(asset_id INTEGER PRIMARY KEY REFERENCES org_asset_register(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE org_asset_movements(id INTEGER PRIMARY KEY,asset_id INTEGER NOT NULL REFERENCES org_asset_register(id),document_id INTEGER NOT NULL UNIQUE REFERENCES acc_documents(id),journal_id INTEGER NOT NULL REFERENCES journals(id),kind TEXT NOT NULL CHECK(kind IN('depreciation','disposal')),amount INTEGER NOT NULL,through_month TEXT);
